-- CODE
using System;

public class BuyWithHP : Item
{
	public static string staticID = "BuyWithHP";

	private NumVarStatMod costMod;

	private StoreItem boughtItem;

	private int goldDiff;

	public BuyWithHP()
	{
		ID = staticID;
		category = Category.Misc;
		costMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Override);
	}

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			StoreItem.globalBuyEventHandlers = (StoreItem.BuyEventHandler)Delegate.Remove(StoreItem.globalBuyEventHandlers, new StoreItem.BuyEventHandler(OnBuyEvent));
			StoreItem.globalBalanceCheckEventHandlers = (StoreItem.BalanceCheckEvent)Delegate.Remove(StoreItem.globalBalanceCheckEventHandlers, new StoreItem.BalanceCheckEvent(OnBalanceCheck));
			if (givenStatus)
			{
				StoreItem.globalBuyEventHandlers = (StoreItem.BuyEventHandler)Delegate.Combine(StoreItem.globalBuyEventHandlers, new StoreItem.BuyEventHandler(OnBuyEvent));
				StoreItem.globalBalanceCheckEventHandlers = (StoreItem.BalanceCheckEvent)Delegate.Combine(StoreItem.globalBalanceCheckEventHandlers, new StoreItem.BalanceCheckEvent(OnBalanceCheck));
			}
		}
	}

	public void OnBalanceCheck(Player givenPlayer, StoreItem givenItem)
	{
		if (!(givenPlayer != parentPlayer) && !(givenItem == boughtItem) && Player.goldWallet.balance < givenItem.Cost)
		{
			goldDiff = givenItem.Cost - Player.goldWallet.balance;
			Player.goldWallet.Withdraw(Player.goldWallet.balance);
			givenItem.costStat.AddMod(costMod);
			boughtItem = givenItem;
			AttackInfo attackInfo = new AttackInfo();
			attackInfo.skillID = "BuyWithHP";
			attackInfo.damage = goldDiff;
			parentPlayer.health.TakeDamage(attackInfo, null, critPreCalculated: true);
		}
	}

	public void OnBuyEvent(Player givenPlayer, StoreItem givenItem)
	{
		if (givenPlayer == parentPlayer && givenItem == boughtItem)
		{
			givenItem.costStat.RemoveMod(costMod);
		}
	}
}

