using UnityEngine;

public class ChargeFamiliarItem : Item
{
	private ChargeFamiliar currentFamiliar;

	private ElementType currentElement;

	public ChargeFamiliarItem(string givenID, ElementType givenElement)
	{
		ID = givenID;
		category = Category.Misc;
		currentElement = givenElement;
		parentGroupID = ChargeFamiliarGroupItem.staticID;
	}

	public override void Activate()
	{
		if (!GroupItemCreated(ChargeFamiliarGroupItem.staticID) && SetParentAsPlayer())
		{
			currentFamiliar = Globals.ChaosInst<ChargeFamiliar>(ChargeFamiliar.Prefab, null, parentPlayer.transform.position, Quaternion.identity);
			currentFamiliar.gameObject.name = parentPlayer.gameObject.name + currentFamiliar.gameObject.name;
			currentFamiliar.parentEntity = parentPlayer;
			currentFamiliar.parentTransform = parentPlayer.hurtBoxTransform;
			parentPlayer.playerSummonsList.Add(currentFamiliar.gameObject);
			currentFamiliar.doNotTargetList = parentPlayer.playerSummonsList;
			currentFamiliar.HandleElement(currentElement);
		}
	}

	public override void Deactivate()
	{
		if (!(currentFamiliar == null) && SetParentAsPlayer())
		{
			parentPlayer.playerSummonsList.Remove(currentFamiliar.gameObject);
			if (currentFamiliar.fsm != null && currentFamiliar.fsm.HasState("Dead"))
			{
				currentFamiliar.fsm.QueueChangeState("Dead");
			}
			else
			{
				Object.Destroy(currentFamiliar.gameObject);
			}
		}
	}
}

