using System;
using UnityEngine;

public class DamageUpWithBossPerfect : Item
{
	public static string staticID = "DamageUpWithBossPerfect";

	private NumVarStatMod damageMod;

	protected override string ExtraInfo => PercentToStr(damageMod, "+");

	public DamageUpWithBossPerfect()
	{
		ID = staticID;
		category = Category.Offense;
		destroyOnDrop = true;
		damageMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			StatManager.ModifyAllStatData(damageMod, parentSkillCategory, StatData.damageStr, IgnoreStatusConditional, givenStatus);
			BossRoomEventHandler.bossPerfectEventHandlers = (BossRoomEventHandler.BossPerfectEventHandler)Delegate.Remove(BossRoomEventHandler.bossPerfectEventHandlers, new BossRoomEventHandler.BossPerfectEventHandler(OnBossPerfect));
			if (givenStatus)
			{
