using System;
using System.Collections.Generic;

public class DamageUpWithDiffElement : Item
{
	public static string staticID = "DamageUpWithDiffElement";

	private NumVarStatMod damageMod;

	private bool activated;

	private HashSet<ElementType> elementSet = new HashSet<ElementType>();

	protected override string ExtraInfo => PercentToStr(damageMod, "+");

	public DamageUpWithDiffElement()
	{
		ID = staticID;
		category = Category.Offense;
		damageMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		if (SetParentAsPlayer())
		{
			SetEventHandlers(givenStatus: true);
			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
			CheckActivatePowerup();
		}
	}

	public override void Deactivate()
	{
		if (!(parentPlayer == null))
		{
			SetEventHandlers(givenStatus: false);
			DeactivatePowerup();
			RemoveFromItemBar();
		}
	}

	private void SetEventHandlers(bool givenStatus)
	{
		StatManager.ModifyAllStatData(damageMod, parentSkillCategory, "damage", IgnoreStatusConditional, givenStatus);
		Player player = parentPlayer;
		player.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Remove(player.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(CheckActivatePowerup));
		if (givenStatus)
