			player2.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Combine(player2.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(CheckActivatePowerup));
		}
	}

	public void CheckActivatePowerup(Player.SkillState newSkill = null, int skillSlotNum = 0)
	{
		if (parentPlayer == null)
		{
			return;
		}
		elementSet.Clear();
		for (int i = 0; i < parentPlayer.assignedSkills.Length; i++)
		{
			if (parentPlayer.assignedSkills[i] != null)
			{
				elementSet.Add(parentPlayer.assignedSkills[i].element);
			}
		}
		if (elementSet.Count >= 2)
		{
			damageMod.modValue = (float)(elementSet.Count - 1) * 0.04f;
			ActivatePowerup();
		}
		else if (activated)
		{
			damageMod.modValue = 0f;
			DeactivatePowerup();
		}
	}

