using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class DeathProofCrown : OnTakeDamageItem
{
	public static string staticID = "DeathProofCrown";

	private static Dictionary<int, bool> idReadyDict = new Dictionary<int, bool>();

	private BoolVarStatMod deathProofMod;

	private ChaosQuickStopwatch activeStopwatch = new ChaosQuickStopwatch(3.5f);

	private float finalHealPercentage = 0.05f;

	private bool itemHeld;

	private int parentID = -1;

	private bool ItemReady
	{
		get
		{
			return !idReadyDict.ContainsKey(parentID) || idReadyDict[parentID];
		}
		set
		{
			idReadyDict[parentID] = value;
		}
	}

	public DeathProofCrown()
	{
		ID = staticID;
		category = Category.Defense;
		activateOnEvent = true;
		deathProofMod = new BoolVarStatMod(ID, newModValue: true);
	}

	public override void Activate()
	{
		if (SetParentAsPlayer())
		{
			parentID = parentPlayer.playerID;
			itemHeld = true;
			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
			SetItemBarStatus();
			GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Remove(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoad));
			GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Combine(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoad));
			base.Activate();
		}
	}

	public override void Deactivate()
	{
		SetDeathProofStatus(parentPlayer, givenStatus: false);
		RemoveFromItemBar();
		itemHeld = false;
		GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Remove(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoad));
		base.Deactivate();
	}

	public override void OnTakeDamageEvent(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (!GameController.pvpOn && ItemReady && !(parentPlayer == null) && !(parentPlayer.health == null) && !parentPlayer.health.deathProof.CurrentValue && parentPlayer.health.CurrentHealthValue <= givenAtkInfo.damage && parentPlayer.health.CurrentShieldValue < givenAtkInfo.damage && !parentPlayer.health.GuardNextAtk)
		{
			parentPlayer.StartCoroutine(StartDeathProof(parentPlayer));
			parentPlayer.OverdriveProgress += 999f;
		}
	}

	private void OnLevelLoad(string a, string b)
	{
		idReadyDict.Clear();
		SetItemBarStatus();
	}

	private void SetItemBarStatus()
	{
		if (itemHeld)
		{
			if (activeStopwatch.IsRunning)
			{
				UpdateItemBar(ItemStatusBar.ItemState.Active);
			}
			else if (ItemReady)
			{
				UpdateItemBar(ItemStatusBar.ItemState.Ready);
			}
			else
			{
				UpdateItemBar(ItemStatusBar.ItemState.Disabled);
			}
		}
	}

	private void SetDeathProofStatus(Player givenPlayer, bool givenStatus)
	{
		if (itemHeld && givenPlayer != null && givenPlayer.health != null)
		{
			givenPlayer.health.deathProof.Modify(deathProofMod, givenStatus);
		}
	}

	private IEnumerator StartDeathProof(Player givenPlayer)
	{
		if (givenPlayer == null)
		{
			yield break;
		}
		activeStopwatch.IsRunning = true;
		ItemReady = false;
		SetItemBarStatus();
		SetDeathProofStatus(givenPlayer, givenStatus: true);
		while (activeStopwatch.IsRunning)
		{
			yield return null;
		}
		if (!(givenPlayer == null))
		{
			SetItemBarStatus();
			SetDeathProofStatus(givenPlayer, givenStatus: false);
			if (givenPlayer != null)
			{
				givenPlayer.health.RestoreHealth(Mathf.CeilToInt(givenPlayer.health.healthStat.ModifiedValue * finalHealPercentage));
			}
		}
	}
}

