public class EleArcanaUnlockCountItem : ArcanaCountItem
{
	public ElementType element;

	public float baseChance;

	public float incChance;

	public NumVarStatMod chanceMod;

	protected override string ExtraInfo => PercentToStr(chanceMod, "+");

	public EleArcanaUnlockCountItem(string givenID, ElementType givenElement, float givenBase = 0.02f, float givenIncrease = 0.005f)
	{
		ID = givenID;
		element = givenElement;
		parentGroupID = ArcanaCountGroupItem.staticID;
		baseChance = givenBase;
		incChance = givenIncrease;
		chanceMod = new NumVarStatMod(givenID, baseChance);
	}

	public override bool ArcanaConditional(Player.SkillState givenSkill)
	{
		return givenSkill != null && givenSkill.isUnlocked && givenSkill.element == element;
	}

	public override void ApplyMods(bool givenStatus, int givenCount)
	{
		if (givenStatus)
		{
			chanceMod.modValue = baseChance + incChance * (float)givenCount;
		}
	}
}

