public class ExtraBasicCombo : Item
{
	public static string staticID = "ExtraBasicCombo";

	public ExtraBasicCombo()
	{
		ID = staticID;
		category = Category.Misc;
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			Player.ModifySkills(parentPlayer, AppliedCondition, AppliedResult, givenStatus);
		}
	}

	private bool AppliedCondition(Player.SkillState givenSkill)
	{
		return givenSkill?.isBasic ?? false;
	}

	private void AppliedResult(Player.SkillState givenSkill, bool givenStatus)
	{
		if (givenSkill != null)
		{
			(givenSkill as Player.MeleeAttackState).maxComboCount += (givenStatus ? 1 : (-1));
			(givenSkill as Player.MeleeAttackState).repeatFinalHit = givenStatus;
		}
	}
}

