using System;

public class FireAuraItem : Item
{
	public static string staticID = "FireAura";

	private FireAura curFireAura;

	private StatData dmgStatData;

	private SyncedNumVarStat dmgVarStat;

	private bool lockDmgUpdate;

	public FireAuraItem()
	{
		ID = staticID;
		category = Category.Offense;
		parentGroupID = AuraGroupItem.staticID;
	}

	public override void Activate()
	{
		if (!GroupItemCreated(AuraGroupItem.staticID) && SetParentAsPlayer())
		{
			curFireAura = Globals.ChaosInst<FireAura>(FireAura.Prefab, parentPlayer.playerObjTrans, parentPlayer.transform.position);
			curFireAura.attack.SetAttackInfo(parentPlayer.skillCategory, ID);
			curFireAura.followScript.followTransform = parentPlayer.transform;
			Player.playerHideEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerHideEventHandlers, new Player.PlayerEventHandler(HideEventHandler));
			Player.playerShowEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerShowEventHandlers, new Player.PlayerEventHandler(ShowEventHandler));
			Player.playerHideEventHandlers = (Player.PlayerEventHandler)Delegate.Combine(Player.playerHideEventHandlers, new Player.PlayerEventHandler(HideEventHandler));
			Player.playerShowEventHandlers = (Player.PlayerEventHandler)Delegate.Combine(Player.playerShowEventHandlers, new Player.PlayerEventHandler(ShowEventHandler));
			dmgStatData = StatManager.GetSkillData(parentPlayer.skillCategory, ID);
			if (dmgStatData != null && dmgStatData.numVarStatDict != null && dmgStatData.numVarStatDict.ContainsKey("damage"))
			{
				dmgVarStat = dmgStatData.numVarStatDict["damage"];
				SyncedNumVarStat syncedNumVarStat = dmgVarStat;
				syncedNumVarStat.statChangedEventHandlers = (VarStat<float>.StatChangedEventHandler)Delegate.Combine(syncedNumVarStat.statChangedEventHandlers, new VarStat<float>.StatChangedEventHandler(OnDmgChange));
			}
		}
	}

	public override void Deactivate()
	{
		if (parentPlayer != null && curFireAura != null)
		{
			curFireAura.Disable();
		}
		Player.playerHideEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerHideEventHandlers, new Player.PlayerEventHandler(HideEventHandler));
		Player.playerShowEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerShowEventHandlers, new Player.PlayerEventHandler(ShowEventHandler));
		if (dmgVarStat != null)
		{
			SyncedNumVarStat syncedNumVarStat = dmgVarStat;
			syncedNumVarStat.statChangedEventHandlers = (VarStat<float>.StatChangedEventHandler)Delegate.Remove(syncedNumVarStat.statChangedEventHandlers, new VarStat<float>.StatChangedEventHandler(OnDmgChange));
		}
	}

	private void OnDmgChange()
	{
		if (!lockDmgUpdate && curFireAura != null && curFireAura.attack != null)
		{
			lockDmgUpdate = true;
			curFireAura.attack.SetAttackInfo(parentPlayer.skillCategory, ID);
			lockDmgUpdate = false;
		}
	}

	private void HideEventHandler(Player givenPlayer)
	{
		if (givenPlayer != null && givenPlayer == parentPlayer && curFireAura != null)
		{
			curFireAura.gameObject.SetActive(value: false);
		}
	}

	private void ShowEventHandler(Player givenPlayer)
	{
		if (givenPlayer != null && givenPlayer == parentPlayer && curFireAura != null)
		{
			curFireAura.gameObject.SetActive(value: true);
		}
	}
}

