using UnityEngine;

public class GradCap : HeadgearItem
{
	public static string staticID = "GradCap";

	private NumVarStatMod platUpMod;

	private static GameObject _prefab;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Headgear/GradCap.prefab");
			}
			return _prefab;
		}
	}

	public GradCap()
	{
		ID = staticID;
		category = Category.Misc;
		parentCombineID = GradSet.staticID;
		headgearPrefab = Prefab;
		platUpMod = new NumVarStatMod(GradSet.modIDStr, 1f);
	}

	public override void Activate()
	{
		if (SetParentAsPlayer())
		{
			base.Activate();
			if (parentPlayer.inventory.ContainsItem(GradBouquet.staticID))
			{
				parentPlayer.inventory.AddItem(GradSet.staticID, showNotice: false, ignoreMax: true);
				parentPlayer.inventory.RemoveItem(GradBouquet.staticID, forceOverride: true);
				parentPlayer.inventory.RemoveItem(staticID);
			}
			else
			{
				LootManager.globalPlatModifier.AddMod(platUpMod);
			}
		}
	}

	public override void Deactivate()
	{
		base.Deactivate();
		if (!Inventory.BothPlayersHaveItem(staticID) && !Inventory.EitherPlayerHasItem(GradSet.staticID))
		{
			LootManager.globalPlatModifier.RemoveMod(platUpMod);
		}
	}
}

