using System;

public class MeleeBasicNegatesProjectiles : Item
{
	public static string staticID = "MeleeBasicNegatesProjectiles";

	private Player.MeleeAttackState currentMA;

	public MeleeBasicNegatesProjectiles()
	{
		ID = staticID;
		category = Category.Misc;
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			Player.ModifySkills(parentPlayer, IsBasicAndMelee, ApplyEventHandler, givenStatus);
		}
	}

	private bool IsBasicAndMelee(Player.SkillState givenSkill)
	{
		return givenSkill != null && givenSkill.isBasic && givenSkill.isMeleeSkill;
	}

	private void ApplyEventHandler(Player.SkillState givenSkill, bool givenStatus)
	{
		Player player = parentPlayer;
		player.skillExecEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillExecEventHandlers, new Player.SkillEventHandler(OnMeleeBasicExec));
		if (givenStatus)
		{
			Player player2 = parentPlayer;
