public class OverdriveDefense : OnTakeDamageItem
{
	public static string staticID = "OverdriveDefense";

	private static int odLoseVal = 35;

	public OverdriveDefense()
	{
		ID = staticID;
		category = Category.Defense;
		activateOnPreShield = true;
	}

	public override void Activate()
	{
		if (SetParentAsPlayer())
		{
			base.Activate();
		}
	}

	public override void OnPreShieldEvent(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (givenAtkInfo != null && !(parentPlayer == null) && !(parentPlayer.OverdriveProgress < (float)odLoseVal) && !parentPlayer.health.GuardNextAtk && !parentPlayer.health.invulnerable)
		{
			parentPlayer.OverdriveProgress -= odLoseVal;
			parentPlayer.health.CurrentShieldValue += givenAtkInfo.damage;
		}
	}
}

