using System;
using System.Collections.Generic;
using UnityEngine;

public class PaperDefense : OnTakeDamageItem
{
	public static string staticID = "PaperDefense";

	private static Dictionary<int, int> idDamageDict = new Dictionary<int, int>();

	private NumVarStatMod armorMod;

	private float baseArmorValue = 0.02f;

	private int maxDamageValue = 1000;

	private int parentID = -1;

	private int DamageValue
	{
		get
		{
			return idDamageDict.ContainsKey(parentID) ? idDamageDict[parentID] : 0;
		}
		set
		{
			idDamageDict[parentID] = value;
			armorMod.modValue = (float)value * 0.0001f + baseArmorValue;
		}
	}

	protected override string ExtraInfo => PercentToStr(armorMod, "+");

	public PaperDefense()
	{
		ID = staticID;
		category = Category.Defense;
		activateOnActual = true;
		RunData.runResetEventHandlers = (RunData.RunEvent)Delegate.Remove(RunData.runResetEventHandlers, new RunData.RunEvent(OnRunReset));
		RunData.runResetEventHandlers = (RunData.RunEvent)Delegate.Combine(RunData.runResetEventHandlers, new RunData.RunEvent(OnRunReset));
		armorMod = new NumVarStatMod(ID, baseArmorValue);
	}

	private static void OnRunReset()
	{
		idDamageDict.Clear();
	}

	public override void OnTakeDamageActual(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (!(parentPlayer == null) && givenAtkInfo != null && givenAtkInfo.damage > 0 && DamageValue < maxDamageValue)
		{
			ApplyDefenseMod(givenStatus: true, givenAtkInfo.damage);
		}
	}

	public override void SetHandlers(bool givenStatus)
	{
		base.SetHandlers(givenStatus);
		SetModStatus(givenStatus);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			parentID = parentPlayer.playerID;
			ApplyDefenseMod(givenStatus);
		}
	}

	private void ApplyDefenseMod(bool givenStatus, int givenValue = 0)
	{
		if (givenStatus)
		{
			DamageValue = Mathf.Min(DamageValue + givenValue, maxDamageValue);
		}
		parentPlayer.health.armorStat.Modify(armorMod, givenStatus);
	}
}

