using System;
using UnityEngine;

public class PlayerWinItem : Item
{
	public static string staticID = "PlayerWin";

	private static string chaosEleStr = "Chaos";

	private static float critDmgInc = 0.25f;

	private NumVarStatMod critDmgMod;

	private NumVarStatMod outfitPaletteMod;

	private NevesAura nevesAura;

	private int chaosCounter;

	protected override string ExtraInfo => PercentToStr(critDmgMod, "+");

	public PlayerWinItem()
	{
		ID = staticID;
		category = Category.Misc;
		combineOnly = true;
		critDmgMod = new NumVarStatMod(ID, 0f);
		outfitPaletteMod = new NumVarStatMod(ID, 23f, 2, VarStatModType.Override);
	}

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		if (!SetParentAsPlayer())
		{
			return;
		}
		StatManager.ModifyAllStatData(critDmgMod, parentSkillCategory, StatData.critDmgStr, ChaosApplyConditional, givenStatus);
		Player player = parentPlayer;
		player.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillPickUpEventHandlers, new Player.SkillEventHandler(OnPickUpSkill));
		Player player2 = parentPlayer;
		player2.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Remove(player2.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssign));
		if (givenStatus)
		{
			Player player3 = parentPlayer;
			player3.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player3.skillPickUpEventHandlers, new Player.SkillEventHandler(OnPickUpSkill));
			Player player4 = parentPlayer;
			player4.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Combine(player4.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssign));
			CalculateModValue();
		}
		else
		{
			RemoveFromItemBar();
			ToggleOutfit(givenStatus: false);
			if (nevesAura != null)
			{
				nevesAura.Reset();
			}
		}
	}

	private void OnPickUpSkill(Player.SkillState ss)
	{
		CalculateModValue();
	}

	private void OnSkillAssign(Player.SkillState ss, int num)
	{
		CalculateModValue();
	}

	private void CalculateModValue()
	{
		if (parentPlayer == null || parentPlayer.assignedSkills == null)
		{
			return;
		}
		int num = 0;
		for (int i = 0; i < parentPlayer.assignedSkills.Length; i++)
		{
			if (IsChaosSkill(parentPlayer.assignedSkills[i]))
			{
				num++;
			}
		}
		if (IsChaosSkill(parentPlayer.stockSkill))
		{
			num++;
		}
		critDmgMod.modValue = (float)num * critDmgInc;
		UpdateItemBar((num > 0) ? ItemStatusBar.ItemState.Active : ItemStatusBar.ItemState.Disabled);
		ToggleOutfit(num >= 7);
	}

	private bool IsChaosSkill(Player.SkillState givenSkill)
	{
		return givenSkill != null && givenSkill.element == ElementType.Chaos;
	}

	private bool ChaosApplyConditional(StatData givenStatData)
	{
		return !givenStatData.GetValue<bool>(StatData.isStatStr) && givenStatData.GetValue<string>(StatData.eleStr) == chaosEleStr;
	}

	private void ToggleOutfit(bool givenStatus)
	{
		parentPlayer.SetPlayerOutfitColor(outfitPaletteMod, givenStatus);
		parentPlayer.OutlineColorDisabled = ((!givenStatus) ? Player.OutlineColorDisabledDefault : new Color(0f, 0f, 0f, 0.2f));
		if (parentPlayer.spriteRenderer != null)
		{
			if (!parentPlayer.overdriveReady)
			{
				parentPlayer.spriteRenderer.material.SetColor("_OutlineColor", parentPlayer.OutlineColorDisabled);
			}
			if (givenStatus && nevesAura == null)
			{
				nevesAura = NevesAura.Create(parentPlayer, parentPlayer.spriteRenderer.transform, ElementType.Chaos);
			}
		}
		if (nevesAura != null)
		{
			nevesAura.SetStatus(givenStatus);
		}
	}
}

