using Chaos.ArrayExtensions;
using UnityEngine;

public class PotionPack : ResurrectItem
{
	public static string staticID = "PotionPack";

	private static GameObject headgearPrefab;

	public Headgear curHeadgear;

	private int spawnCount = 5;

	private bool resurrectUsed;

	public PotionPack()
	{
		ID = staticID;
		category = Category.Defense;
		destroyOnDrop = true;
		resHealthValue = 0.05f;
		priority = 5;
		if (headgearPrefab == null)
		{
			headgearPrefab = ChaosBundle.Get("Assets/Prefabs/Headgear/Corsair.prefab");
		}
	}

	public override void Activate()
	{
		if (!(parentEntity == null))
		{
			curHeadgear = Globals.ChaosInst<Headgear>(headgearPrefab, (!(parentEntity.headPosition == null)) ? parentEntity.headPosition.transform : parentEntity.transform);
			curHeadgear.Initialize(parentEntity, ID);
			resurrectUsed = false;
		}
	}

	public override void Deactivate()
	{
		curHeadgear.Hide(destroyOnHide: true);
		if (resurrectUsed)
		{
			spawnCount = 3;
		}
		if (parentEntity != null && Globals.InGameScene(string.Empty) && GameController.activePlayers.Contains(parentEntity))
		{
			LootManager.DropHealth(parentEntity.transform.position, spawnCount);
		}
	}

	public override void ResurrectPlayer()
	{
		resurrectUsed = true;
		base.ResurrectPlayer();
	}
}

