	{
		Projectile.globalProjectileWallCollisionEvents = (Projectile.GlobalProjectileWallCollisionEvent)Delegate.Remove(Projectile.globalProjectileWallCollisionEvents, new Projectile.GlobalProjectileWallCollisionEvent(OnWallHit));
