using System;
using UnityEngine;

public class ReflectProjectileShield : Item
{
	public static string staticID = "ReflectProjectileShield";

	private ReflectShield reflectShield;

	public ReflectProjectileShield()
	{
		ID = staticID;
		category = Category.Defense;
	}

	public override void Activate()
	{
		if (!(parentEntity == null))
		{
			SetEventHandlers(givenStatus: true);
			reflectShield = Globals.ChaosInst<ReflectShield>(ReflectShield.Prefab, parentEntity.transform, parentEntity.transform.position);
			reflectShield.parentEntity = parentEntity;
			reflectShield.parentObject = parentEntity.gameObject;
			reflectShield.followTrans = parentEntity.hurtBoxTransform;
			reflectShield.skillCategory = parentSkillCategory;
			reflectShield.reflectScript.reflectChance = 1f;
			reflectShield.shieldScale = 1f;
			reflectShield.useReflectCount = true;
			reflectShield.availableReflectCount = 1;
			reflectShield.useDuration = false;
			reflectShield.useRefreshTimer = true;
			reflectShield.refreshTime = 30f;
		}
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
		if (reflectShield != null && reflectShield.gameObject != null)
		{
			UnityEngine.Object.Destroy(reflectShield.gameObject);
		}
	}

	private void SetEventHandlers(bool givenStatus)
	{
		SetParentAsPlayer();
		Player.playerHideEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerHideEventHandlers, new Player.PlayerEventHandler(HideEventHandler));
		Player.playerShowEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerShowEventHandlers, new Player.PlayerEventHandler(ShowEventHandler));
		if (givenStatus)
		{
			Player.playerHideEventHandlers = (Player.PlayerEventHandler)Delegate.Combine(Player.playerHideEventHandlers, new Player.PlayerEventHandler(HideEventHandler));
			Player.playerShowEventHandlers = (Player.PlayerEventHandler)Delegate.Combine(Player.playerShowEventHandlers, new Player.PlayerEventHandler(ShowEventHandler));
		}
	}

	private void HideEventHandler(Player givenPlayer)
	{
		if (givenPlayer == parentPlayer)
		{
			reflectShield.SetActiveStatus(givenStatus: false);
		}
	}

	private void ShowEventHandler(Player givenPlayer)
	{
		if (givenPlayer == parentPlayer)
		{
			reflectShield.SetActiveStatus(givenStatus: true);
		}
	}
}

