using System;

public class RelicDiscount : Item
{
	public static string staticID = "RelicDiscount";

	private NumVarStatMod discountMod;

	protected override string ExtraInfo => PercentToStr(discountMod, "-");

	public RelicDiscount()
	{
		ID = staticID;
		category = Category.Misc;
		parentGroupID = DiscountGroupItem.staticID;
		discountMod = new NumVarStatMod(ID, -0.2f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		if (!givenStatus || !GroupItemCreated(parentGroupID))
		{
			ApplyCostMods(givenStatus);
			ItemStoreItem.spawnEventHandlers = (ItemStoreItem.SpawnEventHandler)Delegate.Remove(ItemStoreItem.spawnEventHandlers, new ItemStoreItem.SpawnEventHandler(OnItemSpawn));
			if (givenStatus)
			{
				ItemStoreItem.spawnEventHandlers = (ItemStoreItem.SpawnEventHandler)Delegate.Combine(ItemStoreItem.spawnEventHandlers, new ItemStoreItem.SpawnEventHandler(OnItemSpawn));
			}
		}
	}

	private void OnItemSpawn(ItemStoreItem givenItem)
	{
		ApplyDiscountToItem(givenItem, givenStatus: true);
	}

	private void ApplyCostMods(bool givenStatus)
	{
		for (int i = 0; i < ItemStoreItem.currentItems.Count; i++)
		{
			ApplyDiscountToItem(ItemStoreItem.currentItems[i], givenStatus);
		}
	}

	private void ApplyDiscountToItem(StoreItem givenItem, bool givenStatus)
	{
		if (!(givenItem == null) && !givenItem.usePlatinumCost)
		{
			givenItem.costStat.Modify(discountMod, givenStatus);
			givenItem.UpdatePrice();
		}
	}
}

