public class ResurrectItem : Item
{
	protected Player otherPlayer;

	protected float resHealthValue = 0.25f;

	public int priority;

	public virtual bool IsAvailable => true;

	public virtual void ResurrectPlayer()
	{
		if (SetParentAsPlayer())
		{
			Player player = parentPlayer;
			bool originPosition = false;
			float restoreHealthPercentage = resHealthValue;
			player.ResetPlayer(originPosition, fullyRestoreHealth: false, resetState: true, resetOverdrive: true, restoreHealthPercentage);
			FindOtherPlayer();
			TeleportToOtherPlayer();
		}
		HandleReset();
	}

	public virtual void FindOtherPlayer()
	{
		otherPlayer = null;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player.playerID != parentPlayer.playerID && player.fsm.currentStateName != "Dead")
			{
				otherPlayer = player;
				break;
			}
		}
	}

	public virtual void TeleportToOtherPlayer()
	{
		if (otherPlayer != null)
		{
			if (!parentPlayer.TeleportToArea(otherPlayer.transform.position, showSpawnPortal: false))
			{
				parentPlayer.transform.position = otherPlayer.transform.position;
			}
			Player.SpawnAllyPortal(parentPlayer.transform.position);
		}
	}

	public virtual void HandleReset()
	{
		if (parentEntity != null)
		{
			parentEntity.inventory.RemoveItem(ID, forceOverride: true, showNotice: true);
		}
	}
}

