using System;

public class StageMap : Item
{
	public static string staticID = "StageMap";

	public StageMap()
	{
		ID = staticID;
		category = Category.Misc;
	}

	public override void Activate()
	{
		if (NextLevelLoader.InTierScene(string.Empty))
		{
			ActivateTriggers();
			RevealSections();
		}
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		DeactivateTriggers();
		HideSections();
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Remove(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(ActivateTriggers));
		LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Remove(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(RevealSections));
		if (givenStatus)
		{
			LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Combine(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(ActivateTriggers));
			LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Combine(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(RevealSections));
		}
	}

	private void ActivateTriggers()
	{
		foreach (CompassIndicatorTrigger trigger in CompassIndicatorTrigger.Triggers)
		{
			if (!trigger.revealed)
			{
				trigger.Activate(revealedByStageMapVal: true);
			}
		}
	}

	private void DeactivateTriggers()
	{
		foreach (CompassIndicatorTrigger trigger in CompassIndicatorTrigger.Triggers)
		{
			if (trigger.revealed && trigger.revealedByStageMap)
			{
				trigger.Deactivate();
			}
		}
	}

	private void RevealSections()
	{
		foreach (MinimapSection minimapSection in MinimapSection.MinimapSections)
		{
			minimapSection.Reveal();
		}
	}

	private void HideSections()
	{
		foreach (MinimapSection minimapSection in MinimapSection.MinimapSections)
		{
			minimapSection.Hide(excludePlayerReveals: true);
		}
	}
}

