public class SummonCountItem : Item
{
	public static string staticID = "SummonCountItem";

	private NumVarStatMod countMod;

	public SummonCountItem()
	{
		ID = staticID;
		category = Category.Misc;
		parentGroupID = SummonGroupItem.staticID;
		countMod = new NumVarStatMod(ID, 1f);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if ((!givenStatus || !GroupItemCreated(SummonGroupItem.staticID)) && SetParentAsPlayer())
		{
			Player.ModifySkills(parentPlayer, IsSummonSkillConditional, ApplyMods, givenStatus);
		}
	}

	private bool IsSummonSkillConditional(Player.SkillState givenSkill)
	{
		return givenSkill?.isSummonSkill ?? false;
	}

	private void ApplyMods(Player.SkillState givenSkill, bool givenStatus)
	{
		givenSkill.skillData.ModifyMod(StatData.spawnStr, countMod, givenStatus);
	}
}

