using UnityEngine;

public class UnicornMask : HeadgearItem
{
	public static string staticID = "UnicornMask";

	private static GameObject _prefab;

	public NumVarStatMod speedMod;

	public NumVarStatMod delayMod;

	private GameObject rbteBody;

	private GameObject rbteFloor;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Headgear/UnicornMask.prefab");
			}
			return _prefab;
		}
	}

	protected override string ExtraInfo => PercentToStr(speedMod, "+");

	public UnicornMask()
	{
		ID = staticID;
		category = Category.Defense;
		combineOnly = true;
		parentCombineID = string.Empty;
		headgearPrefab = Prefab;
		speedMod = new NumVarStatMod(ID, 0.1f, 10, VarStatModType.Multiplicative);
		delayMod = new NumVarStatMod(ID, -0.75f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		if (!(parentEntity == null))
		{
			base.Activate();
			SetModStatus(givenStatus: true);
			if (rbteBody == null)
			{
				rbteBody = CreateTrail(parentEntity.hurtBoxTransform);
			}
			if (rbteFloor == null)
			{
				rbteFloor = CreateTrail(parentEntity.transform);
			}
			if (rbteBody != null)
			{
				ParticleSystem.EmissionModule emission = rbteBody.GetComponent<ParticleSystem>().emission;
				emission.rate = new ParticleSystem.MinMaxCurve(15f);
			}
			if (SetParentAsPlayer())
			{
				parentPlayer.runSpeedupStat.AddMod(delayMod);
				PoolManager.GetPoolItem<ConfettiEffect>().EmitSingle(75, parentEntity.hurtBoxTransform.position);
				SoundManager.PlayAudio("PopSnap");
				SoundManager.PlayAudio("PartyHorn");
			}
		}
	}

	public override void Deactivate()
	{
		base.Deactivate();
		SetModStatus(givenStatus: false);
		if (parentPlayer != null)
		{
			parentPlayer.runSpeedupStat.RemoveMod(delayMod);
		}
		if (rbteBody != null)
		{
			Object.Destroy(rbteBody);
		}
		if (rbteFloor != null)
		{
			Object.Destroy(rbteFloor);
		}
	}

	public void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			parentPlayer.movement.moveSpeedStat.Modify(speedMod, givenStatus);
			parentPlayer.runSpeedupStat.Modify(delayMod, givenStatus);
		}
	}

	private GameObject CreateTrail(Transform givenTrans)
	{
		return (!(givenTrans == null)) ? Object.Instantiate(RainbowTrail.RainbowPrefab, givenTrans.position, Quaternion.identity, givenTrans) : null;
	}
}

