public class WanderersDoll : SignatureModItem
{
	public static string staticID = "WanderersDoll";

	private NumVarStatMod odPauseMod;

	private NumVarStatMod odGainMod;

	private NumVarStatMod odDecayMod;

	private NumVarStatMod odDamageMod;

	public WanderersDoll()
	{
		ID = staticID;
		category = Category.Misc;
		parentCombineID = WanderersSet.staticID;
		isCursed = true;
		odPauseMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Override);
		odGainMod = new NumVarStatMod(ID, 2f, 10, VarStatModType.Multiplicative);
		odDecayMod = new NumVarStatMod(ID, 2.5f, 10, VarStatModType.Multiplicative);
		odDamageMod = new NumVarStatMod(ID, -0.5f, 10, VarStatModType.Multiplicative);
	}

