				base.SetItemStatus(givenStatus);
				parentPlayer.SetODPauseValue(odPauseMod, givenStatus);
				parentPlayer.overdriveBuildDecayRate.Modify(odDecayMod, givenStatus);
				StatManager.ModifyAllStatData(odGainMod, parentSkillCategory, StatData.odProgStr, IgnoreStatusConditional, givenStatus);
			}
		}
	}

	public override void SetModStatus(bool givenStatus)
	{
		if (currentSig != null)
		{
			currentSig.skillData.ModifyMod(StatData.odDmgStr, odDamageMod, givenStatus);
