using System;
using UnityEngine;

public class WaterArcanaCountItem : EleArcanaUnlockCountItem
{
	public static string staticID = "WaterArcanaCountItem";

	public WaterArcanaCountItem()
		: base(staticID, ElementType.Water)
	{
		category = Category.Misc;
	}

	public override bool SetStatus(bool givenStatus)
	{
		if (!base.SetStatus(givenStatus))
		{
			return false;
		}
		Player player = parentPlayer;
		player.skillExecEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillExecEventHandlers, new Player.SkillEventHandler(OnSkillExec));
		if (givenStatus)
		{
			Player player2 = parentPlayer;
			player2.skillExecEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player2.skillExecEventHandlers, new Player.SkillEventHandler(OnSkillExec));
		}
		return true;
	}

	private void OnSkillExec(Player.SkillState givenSkill)
	{
		if (parentPlayer == null || givenSkill == null || givenSkill.isBasic || givenSkill.isDash || !(UnityEngine.Random.value < chanceMod.modValue))
		{
			return;
		}
		for (int num = parentPlayer.assignedSkills.Length - 1; num >= 0; num--)
		{
			if (parentPlayer.assignedSkills[num] != null)
			{
				parentPlayer.assignedSkills[num].cooldownRef.ReduceTimePercentage(0.5f);
			}
		}
		Vector2 vector = parentPlayer.transform.position + Vector3.up;
		WaterHitEffect poolItem = PoolManager.GetPoolItem<WaterHitEffect>();
		int? particleCount = 1;
		Vector3? position = vector;
		Vector3? localEulerAngles = Globals.GetRotationVector(Vector2.down);
		poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
		particleCount = 1;
		localEulerAngles = vector + Vector2.up;
		position = Globals.GetRotationVector(Vector2.down);
		poolItem.EmitSingle(particleCount, localEulerAngles, null, position);
		SoundManager.PlayWithDistAndSPR("WaterArcBasic", vector, 0.8f);
	}
}

